add_action('save_post_tmd_equipo', function ($post_id) {
    if (!isset($_POST['tm_eqd_nonce']) || !wp_verify_nonce($_POST['tm_eqd_nonce'], 'tm_eqd_save')) {
        return;
    }

    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {
        return;
    }

    if (!current_user_can('edit_post', $post_id)) {
        return;
    }

    update_post_meta($post_id, '_tm_eqd_destacado', isset($_POST['tm_eqd_destacado']) ? '1' : '0');

    update_post_meta(
        $post_id,
        '_tm_eqd_orden',
        isset($_POST['tm_eqd_orden']) ? absint($_POST['tm_eqd_orden']) : 0
    );

    $condicion = isset($_POST['tm_eqd_condicion'])
        ? sanitize_text_field(wp_unslash($_POST['tm_eqd_condicion']))
        : 'Usado';

    $condiciones_validas = ['Usado', 'Nuevo', 'Reacondicionado'];

    if (!in_array($condicion, $condiciones_validas, true)) {
        $condicion = 'Usado';
    }

    update_post_meta($post_id, '_tm_eqd_condicion', $condicion);

    $campos = [
        '_tm_eqd_modelo' => 'tm_eqd_modelo',
        '_tm_eqd_anio' => 'tm_eqd_anio',
        '_tm_eqd_energia' => 'tm_eqd_energia',
        '_tm_eqd_capacidad' => 'tm_eqd_capacidad',
        '_tm_eqd_altura' => 'tm_eqd_altura',
    ];

    foreach ($campos as $meta_key => $post_key) {
        $valor = isset($_POST[$post_key])
            ? sanitize_text_field(wp_unslash($_POST[$post_key]))
            : '';

        update_post_meta($post_id, $meta_key, $valor);
    }
});

