    <script>
        document.addEventListener('DOMContentLoaded', function () {
            document.querySelectorAll('.tm-eqd-section').forEach(function (section) {
                const viewport = section.querySelector('.tm-eqd-viewport');
                const track = section.querySelector('.tm-eqd-track');
                const cards = Array.from(section.querySelectorAll('.tm-eqd-card'));
                const dotsWrap = section.querySelector('.tm-eqd-dots');

                if (!viewport || !track || !cards.length || !dotsWrap) {
                    return;
                }

                function getPerView() {
                    if (window.matchMedia('(max-width: 640px)').matches) {
                        return 1;
                    }

                    if (window.matchMedia('(max-width: 1024px)').matches) {
                        return 2;
                    }

                    return 3;
                }

                function buildDots() {
                    const perView = getPerView();
                    const pages = Math.ceil(cards.length / perView);

                    dotsWrap.innerHTML = '';

                    if (pages <= 1) {
                        return;
                    }

                    for (let i = 0; i < pages; i++) {
                        const dot = document.createElement('button');
                        dot.type = 'button';
                        dot.className = 'tm-eqd-dot';
                        dot.setAttribute('aria-label', 'Ir al grupo ' + (i + 1));

                        dot.addEventListener('click', function () {
                            const target = cards[i * perView];

                            if (target) {
                                viewport.scrollTo({
                                    left: target.offsetLeft - track.offsetLeft,
                                    behavior: 'smooth'
                                });
                            }
                        });

                        dotsWrap.appendChild(dot);
                    }

                    updateDots();
                }

                function updateDots() {
                    const dots = Array.from(dotsWrap.querySelectorAll('.tm-eqd-dot'));

                    if (!dots.length) {
                        return;
                    }

                    let closest = 0;
                    let distance = Infinity;

                    cards.forEach(function (card, index) {
                        const diff = Math.abs((card.offsetLeft - track.offsetLeft) - viewport.scrollLeft);

                        if (diff < distance) {
                            distance = diff;
                            closest = index;
                        }
                    });

                    const active = Math.round(closest / getPerView());

                    dots.forEach(function (dot, index) {
                        dot.classList.toggle('is-active', index === active);
                    });
                }

                let ticking = false;

                viewport.addEventListener('scroll', function () {
                    if (!ticking) {
                        window.requestAnimationFrame(function () {
                            updateDots();
                            ticking = false;
                        });

                        ticking = true;
                    }
                });

                window.addEventListener('resize', function () {
                    buildDots();
                });

                buildDots();
            });
        });
    </script>

