                .toString()
                .toLowerCase()
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .replace(/\s+/g, ' ')
                .trim();
        }

        const aliases = {
            'contrabalanceadas': 'contrabalanceada',
            'contrabalanceada': 'contrabalanceada',

            'retractiles': 'retractil',
            'retractil': 'retractil',

            'apiladores': 'apilador',
            'apilador': 'apilador',

            'transpaletas': 'transpaleta',
            'transpaleta': 'transpaleta',

            'recogepedidos': 'recogepedido',
            'recogepedido': 'recogepedido',

            'estibadores': 'estibador',
            'estibador': 'estibador',

            'manlift': 'manlift',

            'electrico': 'electrico',
            'electricos': 'electrico',

            'glp': 'glp',
            'diesel': 'diesel',
            'manual': 'manual',

            'venta': 'venta',
            'alquiler': 'alquiler'
        };

        const tipos = [
            'contrabalanceada',
            'retractil',
            'apilador',
            'transpaleta',
            'recogepedido',
            'estibador',
            'manlift'
        ];

        const energias = [
            'electrico',
            'glp',
            'diesel',
            'manual'
        ];

        const modalidades = [
            'venta',
            'alquiler'
        ];

        function getCheckboxValue(checkbox) {
            let value = checkbox.value;

            if (!value || value === 'on') {
                const label = checkbox.closest('label');
                value = label ? label.textContent : '';
            }

            value = normalize(value);

            return aliases[value] || value;
        }

        function hideVentaYAlquilerOption() {
            const labels = Array.from(
                document.querySelectorAll('.tmd-wrap label, .tmd-catalog-layout label')
            );

            labels.forEach(function (label) {
                const text = normalize(label.textContent);

                if (text === 'venta y alquiler') {
                    const checkbox = label.querySelector('input[type="checkbox"]');

                    if (checkbox) {
                        checkbox.checked = false;
                        checkbox.disabled = true;
                    }

                    label.style.display = 'none';
                }
            });
        }

        function getActiveFilters() {
            const filters = {
                tipo: [],
                energia: [],
                modalidad: []
            };

            const checkboxes = Array.from(
                document.querySelectorAll('.tmd-wrap input[type="checkbox"], .tmd-catalog-layout input[type="checkbox"]')
            );

            checkboxes.forEach(function (checkbox) {
                if (!checkbox.checked || checkbox.disabled) return;

                const value = getCheckboxValue(checkbox);

                if (tipos.includes(value)) {
                    filters.tipo.push(value);
                }

                if (energias.includes(value)) {
                    filters.energia.push(value);
                }

                if (modalidades.includes(value)) {
                    filters.modalidad.push(value);
                }
            });

            return filters;
        }

        function productMatchesModalidad(productModalidad, selectedModalidades) {
            if (selectedModalidades.length === 0) return true;

            const modalidad = normalize(productModalidad);

            if (modalidad === 'venta y alquiler' || modalidad === 'venta-y-alquiler') {
                return selectedModalidades.includes('venta') || selectedModalidades.includes('alquiler');
            }

            return selectedModalidades.includes(modalidad);
        }

        function applyFilters() {
            const filters = getActiveFilters();

            cards.forEach(function (card) {
                const tipo = normalize(card.dataset.tipo);
                const energia = normalize(card.dataset.energia);
                const modalidad = normalize(card.dataset.modalidad);

                const matchTipo =
                    filters.tipo.length === 0 || filters.tipo.includes(tipo);

                const matchEnergia =
                    filters.energia.length === 0 || filters.energia.includes(energia);

                const matchModalidad =
                    productMatchesModalidad(modalidad, filters.modalidad);

                const shouldShow = matchTipo && matchEnergia && matchModalidad;

                card.classList.toggle('tmd-card-hidden', !shouldShow);
            });
        }

        hideVentaYAlquilerOption();

        document
            .querySelectorAll('.tmd-wrap input[type="checkbox"], .tmd-catalog-layout input[type="checkbox"]')
            .forEach(function (checkbox) {
                checkbox.addEventListener('change', applyFilters);
            });

        applyFilters();
    });
    </script>
