            if (ignoreKey !== 'uso' && state.uso.length) {
                const cardUsos = (card.dataset.uso || '').split(',').map(slug).filter(Boolean);
                const hasUso = state.uso.some(uso => cardUsos.includes(uso));
                if (!hasUso) return false;
