            if (ignoreKey !== 'anio') {
                const year = toNumber(card.dataset.anio);

                if ((state.anioMin !== YEAR_MIN || state.anioMax !== YEAR_MAX) && year === null) {
                    return false;
                }

                if (year !== null && (year < state.anioMin || year > state.anioMax)) {
                    return false;
                }
            }

            return true;
        }

        function updateSubtipoOptions(state) {
            const el = getFormElements();

            if (!state.equipo) {
                el.subtipo.innerHTML = `<option value="">Primero selecciona tipo de equipo</option>`;
                el.subtipo.disabled = true;
                return;
            }

            const available = getUnique(
                cards
                    .filter(card => card.dataset.equipo === state.equipo)
                    .map(card => card.dataset.subtipo)
            );

            const current = el.subtipo.value;

            el.subtipo.innerHTML = `
                <option value="">Todos los subtipos</option>
                ${available.map(value => `
                    <option value="${value}">${labelMaps.subtipo[value] || pretty(value)}</option>
                `).join('')}
            `;

            if (available.includes(current)) {
                el.subtipo.value = current;
            }

            el.subtipo.disabled = false;
        }

        function updateFabricanteOptions(state) {
            const el = getFormElements();

            if (!state.equipo) {
                el.fabricante.innerHTML = `<option value="">Todos los fabricantes</option>`;
                el.fabricante.disabled = true;
                return;
            }

            const map = new Map();

            cards.forEach(card => {
                if (!cardMatches(card, state, 'fabricante')) return;

                const value = card.dataset.fabricante;
                const label = card.dataset.fabricanteLabel || pretty(value);

                if (value) {
                    map.set(value, label);
                }
            });

            const current = el.fabricante.value;

            const options = Array.from(map.entries())
                .sort((a, b) => a[1].localeCompare(b[1]));

            el.fabricante.innerHTML = `
                <option value="">Todos los fabricantes</option>
                ${options.map(([value, label]) => `
                    <option value="${value}">${label}</option>
                `).join('')}
            `;

            if (map.has(current)) {
                el.fabricante.value = current;
            }

            el.fabricante.disabled = options.length === 0;
        }

        function updateDependentControls(state) {
            const form = getFormElements().form;
            const dependents = form.querySelectorAll('[data-dependent="true"]');

            dependents.forEach(group => {
                if (state.equipo) {
                    group.classList.remove('tmd-hf-disabled');
                    group.querySelectorAll('input, select').forEach(input => input.disabled = false);
                } else {
                    group.classList.add('tmd-hf-disabled');
                    group.querySelectorAll('input, select').forEach(input => input.disabled = true);
                }
            });

            updateSubtipoOptions(state);
            updateFabricanteOptions(state);
        }

        function updateYearLabels() {
            const el = getFormElements();

            let min = parseInt(el.yearMin.value, 10);
            let max = parseInt(el.yearMax.value, 10);

            if (min > max) {
                const active = document.activeElement;

                if (active === el.yearMin) {
                    el.yearMax.value = min;
                    max = min;
                } else {
                    el.yearMin.value = max;
                    min = max;
                }
            }

            el.yearMinLabel.textContent = min;
            el.yearMaxLabel.textContent = max;
        }

        function renderChips(state) {
            const el = getFormElements();
            const chips = [];

            if (state.equipo) {
                chips.push({
                    key: 'equipo',
                    value: state.equipo,
                    label: labelMaps.equipo[state.equipo] || pretty(state.equipo)
                });
            }

            if (state.subtipo) {
                chips.push({
                    key: 'subtipo',
                    value: state.subtipo,
                    label: labelMaps.subtipo[state.subtipo] || pretty(state.subtipo)
                });
            }

            state.energia.forEach(value => {
                chips.push({
                    key: 'energia',
                    value,
                    label: labelMaps.energia[value] || pretty(value)
                });
            });

            if (state.capacidad) {
                chips.push({
                    key: 'capacidad',
                    value: state.capacidad,
                    label: labelMaps.capacidad[state.capacidad] || pretty(state.capacidad)
                });
            }

            if (state.altura) {
                chips.push({
                    key: 'altura',
                    value: state.altura,
                    label: labelMaps.altura[state.altura] || pretty(state.altura)
                });
            }

            state.uso.forEach(value => {
                chips.push({
                    key: 'uso',
                    value,
                    label: labelMaps.uso[value] || pretty(value)
                });
            });

            if (state.fabricante) {
                const selected = el.fabricante.options[el.fabricante.selectedIndex];
                chips.push({
                    key: 'fabricante',
                    value: state.fabricante,
                    label: selected ? selected.textContent : pretty(state.fabricante)
                });
            }

            if (state.anioMin !== YEAR_MIN || state.anioMax !== YEAR_MAX) {
                chips.push({
                    key: 'anio',
                    value: `${state.anioMin}-${state.anioMax}`,
                    label: `${state.anioMin} - ${state.anioMax}`
                });
            }

            el.chips.innerHTML = chips.map(chip => `
                <button type="button" class="tmd-hf-chip" data-key="${chip.key}" data-value="${chip.value}">
                    ${chip.label} ×
                </button>
            `).join('');
        }

        function removeChip(key, value) {
            const el = getFormElements();
            const form = el.form;

            if (key === 'equipo') {
                form.reset();
                el.yearMin.value = YEAR_MIN;
                el.yearMax.value = YEAR_MAX;
            }

            if (key === 'subtipo') {
                el.subtipo.value = '';
            }

            if (key === 'energia' || key === 'uso') {
                const input = form.querySelector(`[name="${key}"][value="${value}"]`);
                if (input) input.checked = false;
            }

            if (key === 'capacidad' || key === 'altura') {
                const checked = form.querySelector(`[name="${key}"]:checked`);
                if (checked) checked.checked = false;
            }

            if (key === 'fabricante') {
                el.fabricante.value = '';
            }

            if (key === 'anio') {
                el.yearMin.value = YEAR_MIN;
                el.yearMax.value = YEAR_MAX;
            }

            refresh();
        }

        function updateUrl(state) {
            const params = new URLSearchParams();

            if (state.equipo) params.set('equipo', state.equipo);
            if (state.subtipo) params.set('subtipo', state.subtipo);
            if (state.energia.length) params.set('energia', state.energia.join(','));
            if (state.capacidad) params.set('capacidad', state.capacidad);
            if (state.altura) params.set('altura', state.altura);
            if (state.uso.length) params.set('uso', state.uso.join(','));
            if (state.fabricante) params.set('fabricante', state.fabricante);

            if (state.anioMin !== YEAR_MIN) params.set('anio_min', state.anioMin);
            if (state.anioMax !== YEAR_MAX) params.set('anio_max', state.anioMax);

            const newUrl = `${window.location.pathname}${params.toString() ? '?' + params.toString() : ''}`;
            window.history.replaceState({}, '', newUrl);
        }

        function applyStateFromUrl() {
            const el = getFormElements();
            const form = el.form;
            const params = new URLSearchParams(window.location.search);

            const equipo = params.get('equipo');

            if (equipo) {
                const input = form.querySelector(`[name="equipo"][value="${equipo}"]`);
                if (input) input.checked = true;
            }

            let state = getState();
            updateDependentControls(state);

            const subtipo = params.get('subtipo');
            if (subtipo) {
                el.subtipo.value = subtipo;
            }

            const energia = params.get('energia');
            if (energia) {
                energia.split(',').forEach(value => {
                    const input = form.querySelector(`[name="energia"][value="${value}"]`);
                    if (input) input.checked = true;
                });
            }

            const capacidad = params.get('capacidad');
            if (capacidad) {
                const input = form.querySelector(`[name="capacidad"][value="${capacidad}"]`);
                if (input) input.checked = true;
            }

            const altura = params.get('altura');
            if (altura) {
                const input = form.querySelector(`[name="altura"][value="${altura}"]`);
                if (input) input.checked = true;
            }

            const uso = params.get('uso');
            if (uso) {
                uso.split(',').forEach(value => {
                    const input = form.querySelector(`[name="uso"][value="${value}"]`);
                    if (input) input.checked = true;
                });
            }

            const fabricante = params.get('fabricante');
            state = getState();
            updateFabricanteOptions(state);

            if (fabricante) {
                el.fabricante.value = fabricante;
            }

            const anioMin = params.get('anio_min');
            const anioMax = params.get('anio_max');

            if (anioMin) el.yearMin.value = anioMin;
            if (anioMax) el.yearMax.value = anioMax;
        }

        function ensureEmptyMessage() {
            let empty = document.querySelector('#tmd-hf-empty');

            if (!empty) {
                empty = document.createElement('div');
                empty.id = 'tmd-hf-empty';
                empty.className = 'tmd-hf-empty';
                empty.style.display = 'none';
                empty.textContent = 'No hay equipos que coincidan con esos filtros.';
                grid.appendChild(empty);
            }

            return empty;
        }

        function applyFilters(state) {
            const empty = ensureEmptyMessage();
            let visibleCount = 0;

            cards.forEach(card => {
                const show = state.equipo && cardMatches(card, state);
                card.classList.toggle('tmd-card-hidden', !show);

                if (show) {
                    visibleCount++;
                }
            });

            empty.style.display = state.equipo && visibleCount === 0 ? '' : 'none';

            return visibleCount;
        }

        function refresh() {
            updateYearLabels();

            let state = getState();

            updateDependentControls(state);

            state = getState();

            const count = applyFilters(state);
            const el = getFormElements();

            if (!state.equipo) {
                el.count.textContent = 'Selecciona un tipo de equipo';
            } else {
                el.count.textContent = `${count} resultado${count === 1 ? '' : 's'}`;
            }

            renderChips(state);
            updateUrl(state);
        }

        function bindEvents() {
            const el = getFormElements();
            const form = el.form;

            form.addEventListener('change', function () {
                refresh();
            });

            form.addEventListener('input', function (event) {
                if (event.target.type === 'range') {
                    refresh();
                }
            });

            el.chips.addEventListener('click', function (event) {
                const chip = event.target.closest('.tmd-hf-chip');
                if (!chip) return;

                removeChip(chip.dataset.key, chip.dataset.value);
            });

            el.clear.addEventListener('click', function () {
                form.reset();
                el.yearMin.value = YEAR_MIN;
                el.yearMax.value = YEAR_MAX;
                refresh();
            });
        }

        enrichCards();
        buildSidebar();
        bindEvents();
        applyStateFromUrl();
        refresh();
    });
    </script>
    <?php
